import { listTemplates } from './QuestionEngine.js';

export const PRACTICE_DIFFICULTIES = Object.freeze(['easy', 'medium', 'hard']);
const rank = { basic: 0, apply: 1, reason: 2 };

// Relative task complexity is selected within each lesson. Some advanced robot
// lessons start at application, so a global 'basic' filter would omit lessons.
export function getDifficultyLevel(difficulty) {
    if (!PRACTICE_DIFFICULTIES.includes(difficulty)) throw new RangeError('Chọn mức độ Dễ, Vừa hoặc Khó.');
    return 'all';
}

export function listAutomaticTemplates({ courseId, lessonId = 'all', difficulty = 'medium' } = {}) {
    getDifficultyLevel(difficulty);
    const scoped = listTemplates({ courseId, lessonId });
    const limits = new Map();
    for (const template of scoped) {
        const key = `${template.courseId}:${template.lessonId}`;
        const current = limits.get(key) || { low: Infinity, high: -Infinity };
        current.low = Math.min(current.low, rank[template.level]);
        current.high = Math.max(current.high, rank[template.level]);
        limits.set(key, current);
    }
    return scoped.filter(template => {
        const { low, high } = limits.get(`${template.courseId}:${template.lessonId}`);
        return difficulty === 'medium' || rank[template.level] === (difficulty === 'easy' ? low : high);
    });
}
